def expected_latency_ms(h, t_accel, t_source):
    # h: 命中率; t_accel: 本地加速扫描耗时(ms); t_source: 回源耗时(ms)
    return h * t_accel + (1 - h) * t_source

for h in (0.0, 0.5, 0.9, 0.99, 1.0):
    print(f'{h:.2f}', round(expected_latency_ms(h, 5, 800), 1), 'ms')

def binary_search(a, x):
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == x:
            return mid
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
